import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.WFmvnizL.js";const p=JSON.parse('{"title":"Nezha Monitoring V2 security and privacy guide","description":"Production security checklist for Nezha Monitoring V2 covering TLS, reverse proxies, real IP, accounts, OAuth2, connection secrets, API Tokens, Agent privileges, remote operations, notifications, backups, and updates.","frontmatter":{"title":"Nezha Monitoring V2 security and privacy guide","description":"Production security checklist for Nezha Monitoring V2 covering TLS, reverse proxies, real IP, accounts, OAuth2, connection secrets, API Tokens, Agent privileges, remote operations, notifications, backups, and updates.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/security.md","filePath":"en_US/guide/security.md","lastUpdated":1785844584000}'),n={name:"en_US/guide/security.md"};function r(s,e,d,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="nezha-monitoring-v2-security-and-privacy-guide" tabindex="-1">Nezha Monitoring V2 security and privacy guide <a class="header-anchor" href="#nezha-monitoring-v2-security-and-privacy-guide" aria-label="Permalink to &quot;Nezha Monitoring V2 security and privacy guide&quot;">​</a></h1><p>Nezha Monitoring V2 can read server state and perform authorized operations, so Dashboard and Agent should be managed as privileged infrastructure components. This page describes trust boundaries and hardening checks. It does not claim that any configuration automatically meets a compliance standard or replace your organization&#39;s risk assessment.</p><h2 id="start-with-the-trust-boundaries" tabindex="-1">Start with the trust boundaries <a class="header-anchor" href="#start-with-the-trust-boundaries" aria-label="Permalink to &quot;Start with the trust boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>Data or capability involved</th><th>Primary controls</th></tr></thead><tbody><tr><td>Browser → Dashboard</td><td>Public status, login credentials, management and operations requests</td><td>HTTPS, strong passwords, user roles, WAF, access control</td></tr><tr><td>Agent → Dashboard</td><td>Host information, IP addresses, resource state, check and task results</td><td>Connection secret, TLS, trusted endpoint, Agent updates</td></tr><tr><td>Dashboard → Agent</td><td>Terminal, file, task, update, NAT, and related operations</td><td>User permissions, PAT scopes, Agent disable settings, auditing and least privilege</td></tr><tr><td>Dashboard → external service</td><td>OAuth2 identity, notification content, DNS updates</td><td>Provider credentials, templates, callback Host, least-privilege API key</td></tr><tr><td>Dashboard local storage</td><td>Users, configuration, secrets, monitoring data, metric history</td><td>File permissions, disk and backup encryption, host isolation, restore tests</td></tr></tbody></table><h2 id="do-these-immediately-after-installation" tabindex="-1">Do these immediately after installation <a class="header-anchor" href="#do-these-immediately-after-installation" aria-label="Permalink to &quot;Do these immediately after installation&quot;">​</a></h2><ol><li>Replace the default Dashboard <code>admin</code> password.</li><li>Configure HTTPS for public endpoints. If TLS terminates at a reverse proxy, protect the proxy-to-Dashboard network path.</li><li>Restrict the Dashboard management surface to users who need to view or administer it.</li><li>Configure backups and test restoration instead of merely checking that backup files exist.</li><li>Update to supported stable Dashboard and Agent releases.</li></ol><h2 id="tls-domains-and-reverse-proxies" tabindex="-1">TLS, domains, and reverse proxies <a class="header-anchor" href="#tls-domains-and-reverse-proxies" aria-label="Permalink to &quot;TLS, domains, and reverse proxies&quot;">​</a></h2><ul><li>Use TLS when browsers or Agents connect over a public network so credentials and monitoring data are not sent in clear text.</li><li>A reverse proxy must forward normal HTTP, WebSocket, and gRPC correctly. An incomplete configuration can leave the web UI working while Agent or terminal traffic fails.</li><li>Set <code>dashboard_host</code> to the stable public web Host and use <code>install_host</code> for the Agent endpoint. Do not conflate them when the endpoints differ.</li><li>Add every public endpoint to <code>reserved_hosts</code> so a normal member cannot create a NAT domain that conflicts with Dashboard.</li><li>Register OAuth2 callback URLs that match trusted Dashboard Hosts. Do not construct callbacks from an untrusted request Host.</li></ul><p>See <a href="/en_US/configuration/dashboard.html">Dashboard configuration</a> and <a href="/en_US/guide/q3.html">Dashboard reverse proxy</a>.</p><h2 id="real-ip-and-the-built-in-waf" tabindex="-1">Real IP and the built-in WAF <a class="header-anchor" href="#real-ip-and-the-built-in-waf" aria-label="Permalink to &quot;Real IP and the built-in WAF&quot;">​</a></h2><p>Trust <code>web_real_ip_header</code> or <code>agent_real_ip_header</code> only when a reverse proxy always covers Dashboard and overwrites that header. A client that can bypass the proxy and reach Dashboard directly may be able to forge it.</p><ul><li>Restrict the Dashboard origin port to trusted proxies or private networks.</li><li>Use the exact header written by the deployed proxy; do not copy a CDN example blindly.</li><li>Changing <code>web_real_ip_header</code> affects how the WAF identifies visitors. A bad value can collapse all users into one IP or trust forged addresses.</li><li>Follow <a href="/en_US/guide/q12.html">Real IP request header</a> for recovery and verification.</li></ul><h2 id="accounts-oauth2-and-sessions" tabindex="-1">Accounts, OAuth2, and sessions <a class="header-anchor" href="#accounts-oauth2-and-sessions" aria-label="Permalink to &quot;Accounts, OAuth2, and sessions&quot;">​</a></h2><ul><li>Give every operator an individual account; do not share an administrator password.</li><li>Grant administrator access only to users who manage system settings, users, or WAF controls.</li><li>OAuth2 is a binding method for local accounts. It does not remove the security responsibility for local accounts or callbacks.</li><li>In production, prefer injecting the JWT signing secret through <code>NZ_JWTSECRETKEY</code> instead of storing it in YAML. Rotating the secret can invalidate active sessions.</li><li>Enable <code>force_auth</code> when a public status view is not required, and also review the guest visibility of each server and service.</li></ul><h2 id="agent-connection-secrets" tabindex="-1">Agent connection secrets <a class="header-anchor" href="#agent-connection-secrets" aria-label="Permalink to &quot;Agent connection secrets&quot;">​</a></h2><p>Treat connection secrets as passwords:</p><ul><li>Never paste an installation command containing <code>NZ_CLIENT_SECRET</code> into a public issue, chat, or log.</li><li>Do not share one secret across unrelated users or environments.</li><li>If exposure is suspected, replace the affected credential and redeploy the corresponding Agents.</li><li>Give every Agent a unique UUID; regenerate it when copying configuration to avoid identity conflicts.</li><li>Use <code>insecure_tls</code> only in a deliberately controlled temporary environment. Do not use it to bypass certificate validation on the public internet.</li></ul><h2 id="api-tokens-and-mcp" tabindex="-1">API Tokens and MCP <a class="header-anchor" href="#api-tokens-and-mcp" aria-label="Permalink to &quot;API Tokens and MCP&quot;">​</a></h2><p>API Tokens (PATs) are intended for scripts and automation and use <code>Authorization: Bearer ...</code>. When creating a Token:</p><ul><li>Grant only the scopes required by the task; do not default to <code>nezha:*</code>.</li><li>Set an expiration and a rotation process.</li><li>Keep it in a secret manager or protected environment variable, not a public repository or client-side page.</li><li>Separate automation accounts from daily administrator accounts so access can be revoked and impact traced independently.</li></ul><p>MCP is disabled by default and accepts PATs only. Once enabled, the tools available to a model or automation client are controlled by Token scope; file transfer also creates temporary streams. Read <a href="/en_US/guide/api.html#mcp-access">API Tokens and MCP</a> before setting <code>enable_mcp</code>.</p><h2 id="remote-terminal-files-tasks-and-nat" tabindex="-1">Remote terminal, files, tasks, and NAT <a class="header-anchor" href="#remote-terminal-files-tasks-and-nat" aria-label="Permalink to &quot;Remote terminal, files, tasks, and NAT&quot;">​</a></h2><p>These features can execute commands, read or write files, establish connections, or change DNS and forwarding state on an Agent host:</p><ul><li>Set <code>disable_command_execute: true</code> on Agents that do not need remote commands.</li><li>Set <code>disable_force_update: true</code> when Dashboard must not force an Agent update, and take responsibility for security updates separately.</li><li>Set <code>disable_nat: true</code> when NAT is not used.</li><li>Restrict server execution, file, delete, and write access with user roles and PAT scopes.</li><li>Close unused terminal and file sessions to release IOStream quota and reduce exposure time.</li><li>Treat Dashboard administrator access as a privileged role that can affect all connected Agents.</li></ul><h2 id="notifications-ddns-and-provider-credentials" tabindex="-1">Notifications, DDNS, and provider credentials <a class="header-anchor" href="#notifications-ddns-and-provider-credentials" aria-label="Permalink to &quot;Notifications, DDNS, and provider credentials&quot;">​</a></h2><ul><li>Notification bodies may include server names, IP addresses, resource state, or custom template data. Review the template and recipients before sending data to a third party.</li><li><code>enable_plain_ip_in_notification</code> is disabled by default. Send full IP addresses only when required.</li><li>Notification and DDNS credentials are redacted in list responses, but edit behavior is documented on the relevant page. Redaction does not mean credentials are absent from disk or backups.</li><li>Give DNS provider Tokens access only to the required zone or records instead of using an account-wide key.</li><li>Before deleting a notification or DDNS provider, confirm that no rule still depends on it.</li></ul><h2 id="data-logs-and-backups" tabindex="-1">Data, logs, and backups <a class="header-anchor" href="#data-logs-and-backups" aria-label="Permalink to &quot;Data, logs, and backups&quot;">​</a></h2><ul><li>Restrict filesystem access to the Dashboard data directory, configuration, SQLite, and TSDB.</li><li>Backups can contain accounts, secrets, IP addresses, server names, and history. Encrypt them and limit readers.</li><li>Stop Dashboard before migration or a consistency-sensitive backup; after restoration, verify users, Agents, services, notifications, and history.</li><li>Debug logs can contain internal paths, error context, or request information. Enable <code>debug</code> only while troubleshooting and protect or remove collected logs afterward.</li><li>Configure an appropriate TSDB retention and free-space threshold. Longer retention increases both storage responsibility and the data exposure window.</li></ul><h2 id="updates-and-supply-chain" tabindex="-1">Updates and supply chain <a class="header-anchor" href="#updates-and-supply-chain" aria-label="Permalink to &quot;Updates and supply chain&quot;">​</a></h2><ul><li>Obtain software only from <a href="https://github.com/nezhahq/nezha/releases" target="_blank" rel="noreferrer">Dashboard Releases</a>, <a href="https://github.com/nezhahq/agent/releases" target="_blank" rel="noreferrer">Agent Releases</a>, or sources referenced by the official installer.</li><li>Read both repositories&#39; notes and create a backup before upgrading; validate on a small number of nodes first.</li><li>Do not run an untrusted theme, community script, or modified Agent. Community projects are outside official compatibility guarantees.</li><li>If automatic or forced Agent updates are disabled, maintain your own version inventory and remediation timeline.</li></ul><h2 id="minimal-monitoring-only-deployment" tabindex="-1">Minimal monitoring-only deployment <a class="header-anchor" href="#minimal-monitoring-only-deployment" aria-label="Permalink to &quot;Minimal monitoring-only deployment&quot;">​</a></h2><p>If you need monitoring but no remote operations, begin with a reduced capability set:</p><ol><li>Expose Dashboard only through HTTPS or a private network.</li><li>Enable <code>force_auth</code> and create only necessary users.</li><li>Disable command execution, forced updates, and NAT on Agents.</li><li>Keep MCP disabled and do not create broad-scope PATs.</li><li>Configure only required notifications and service checks.</li><li>Maintain an encrypted offline or off-site backup and run restoration drills.</li></ol><p>For connection-specific diagnosis, continue with <a href="/en_US/guide/architecture.html">Architecture and data flow</a>, <a href="/en_US/guide/dashboardq.html">Dashboard troubleshooting</a>, and <a href="/en_US/guide/agentq.html">Agent troubleshooting</a>.</p>',34)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
